 static Request ParsePrepare(Dictionary<string,object> packet){string[] keys={"version","containerName","containerSid","stateRoot","executable","executableSHA256","runtimeExecutable","toolRoots"};if(packet.Count!=keys.Length)throw new InvalidDataException();foreach(string key in keys)if(!packet.ContainsKey(key))throw new InvalidDataException();if(!(packet["version"] is int)||(int)packet["version"]!=1)throw new InvalidDataException();var r=new Request{name=Text(packet,"containerName",40),sid=Text(packet,"containerSid",192),state=Canonical(Text(packet,"stateRoot",1024)),executable=Canonical(Text(packet,"executable",1024)),hash=Text(packet,"executableSHA256",64),ownerExecutable=Canonical(Text(packet,"runtimeExecutable",1024))};if(!Regex.IsMatch(r.name,"^gate-code-[0-9a-f]{24}$")||!Regex.IsMatch(r.sid,@"^S-1-15-2-(?:[0-9]+-){6}[0-9]+$")||!Regex.IsMatch(r.hash,"^[0-9a-f]{64}$"))throw new InvalidDataException();string runtime=Path.GetDirectoryName(r.ownerExecutable);if(!String.Equals(Path.GetFileName(r.ownerExecutable),"claude.exe",StringComparison.OrdinalIgnoreCase)||!Regex.IsMatch(Path.GetFileName(runtime),"^Runtime-[0-9a-f]{24}$"))throw new InvalidDataException();r.guardRoot=Path.GetDirectoryName(runtime);if(!Under(r.guardRoot,ActualProfile())||!String.Equals(r.state,Path.Combine(r.guardRoot,"CodeState"),StringComparison.OrdinalIgnoreCase)||!String.Equals(r.executable,Path.Combine(r.guardRoot,"CodeBin",r.hash,"claude.exe"),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException();string install=AppDomain.CurrentDomain.BaseDirectory.TrimEnd('\\');if(String.Equals(Path.GetFileName(install),"resources",StringComparison.OrdinalIgnoreCase))install=Path.GetDirectoryName(install);if(Under(install,r.guardRoot)||Under(r.guardRoot,install)||String.Equals(install,r.guardRoot,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException();var tools=packet["toolRoots"] as IList;if(tools==null||(tools.Count!=0&&tools.Count!=2))throw new InvalidDataException();r.tools